mapper.select:
SELECT sub.id AS id, sub.detail_id AS detailId, d.main_id AS mainId, r.reconciliation_month AS reconciliationMonth, r.supplier_id AS supplierId, r.supplier_name AS supplierName, r.sheet_name AS sheetName, d.row_no AS rowNo, sub.seq_no AS seqNo, d.so_code AS soCode, d.platform_order_no AS platformOrderNo, d.track_no AS trackNo, d.transport_no AS transportNo, d.so_delivery_code AS soDeliveryCode, d.erp_so_code AS erpSoCode, d.erp_platform_order_no AS erpPlatformOrderNo, d.erp_track_no AS erpTrackNo, d.erp_so_delivery_code AS erpSoDeliveryCode, sub.cost_name AS costName, sub.cfg_cost_name AS cfgCostName, sub.actual_amount AS actualAmount, sub.currency AS currency, d.pay_type AS payType, d.weight_logistics AS weightLogistics, d.volume_weight_logistics AS volumeWeightLogistics, d.billing_weight_logistics AS billingWeightLogistics, d.weight_unit AS weightUnit, d.third_length AS thirdLength, d.third_width AS thirdWidth, d.third_height AS thirdHeight, d.cost_count AS costCount, sub.match_status AS matchStatus, sub.match_fail_reason AS matchFailReason, sub.reconciliation_status AS reconciliationStatus, d.create_time AS createTime, d.create_user_name AS createUserName FROM logistics_recon_detail_sub sub INNER JOIN logistics_recon_detail d ON d.id = sub.detail_id AND d.is_deleted = false INNER JOIN logistics_recon r ON r.id = d.main_id AND r.is_deleted = false WHERE ${params.sqlMap.default} and sub.is_deleted = false AND d.main_id = #{params.mainId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
rowNo ASC, seqNo ASC

SELECT sub.match_status AS tabFlag, count(*) AS count FROM logistics_recon_detail_sub sub INNER JOIN logistics_recon_detail d ON d.id = sub.detail_id AND d.is_deleted = false WHERE sub.is_deleted = false AND d.main_id = #{params.mainId}
${params.permissionSql}
GROUP BY sub.match_status
